-- Deployed access policy snapshot for the operational plan section.
CREATE POLICY manjaz_operational_plan_update_guard ON public.records AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (kind <> 'cloud_operational_plan' OR (select auth.uid()) = 'c5b300b1-3f92-42a9-842e-c1717cc42238'::uuid) WITH CHECK (kind <> 'cloud_operational_plan' OR (select auth.uid()) = 'c5b300b1-3f92-42a9-842e-c1717cc42238'::uuid);
CREATE POLICY manjaz_operational_plan_delete_guard ON public.records AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (kind <> 'cloud_operational_plan' OR (select auth.uid()) = 'c5b300b1-3f92-42a9-842e-c1717cc42238'::uuid);
CREATE POLICY manjaz_operational_plan_insert_guard ON public.records AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (kind <> 'cloud_operational_plan' OR (select auth.uid()) = 'c5b300b1-3f92-42a9-842e-c1717cc42238'::uuid);
CREATE POLICY manjaz_operational_plan_admin ON public.records FOR ALL TO authenticated USING (kind = 'cloud_operational_plan' AND (select auth.uid()) = 'c5b300b1-3f92-42a9-842e-c1717cc42238'::uuid) WITH CHECK (kind = 'cloud_operational_plan' AND (select auth.uid()) = 'c5b300b1-3f92-42a9-842e-c1717cc42238'::uuid);